    min: 0.25,
    max: 4,
    step: 0.25,
    description: "Speed",
    hiddenFromList: false,
  },
  ...Interactive.transformSchema,
} as const satisfies InteractivitySchema;

const ELEMENT_PROP_KEYS = new Set(["theme","subject","tag","fontWeight","fly","accent","fontFamily","background","scale","delay","grain","speed"]);

const ELEMENT_PROP_DEFAULTS: Record<string, unknown> = {
  theme: "dark",
  subject: "1.8s",
  tag: "Render time",
  fontWeight: 500,
  fly: 22,
  accent: "#3B5BFD",
  fontFamily: "Geist",
  scale: 1,
  delay: 0,
  grain: true,
  speed: 1,
};

type BracketFocusElementProps = InteractiveBaseProps &
  InteractiveTransformProps &
  ComponentProps<typeof BracketFocusBase>;

const BracketFocusInner = forwardRef<
  HTMLDivElement,
  BracketFocusElementProps & { readonly controls: SequenceControls | undefined }
>(({ controls, name, style, ...rest }, ref) => {
  const outlineRef = useRef<HTMLDivElement>(null);
  useImperativeHandle(ref, () => outlineRef.current as HTMLDivElement, []);
  const componentProps: Record<string, unknown> = { ...ELEMENT_PROP_DEFAULTS };
  const sequenceProps: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(rest)) {
    if (ELEMENT_PROP_KEYS.has(key)) {
      if (value !== undefined) componentProps[key] = value;
    } else {
      sequenceProps[key] = value;
    }
  }
  return (
    <Sequence
      layout="none"
      {...sequenceProps}
      controls={controls}
      name={name ?? "<BracketFocus>"}
      outlineRef={outlineRef}
    >
      <div
        ref={outlineRef}
        style={{
          position: "relative",
          width: "100%",
          height: "100%",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          ...style,
        }}
      >
        <BracketFocusBase
          {...(componentProps as unknown as ComponentProps<typeof BracketFocusBase>)}
        />
      </div>
    </Sequence>
  );
});

export const BracketFocus = Interactive.withSchema({
  Component: BracketFocusInner,
  componentName: "<BracketFocus>",
  componentIdentity: null,
  schema: elementSchema,
  supportsEffects: false,
});
